    /** Read one local file as a data URL. */
    function fileToDataUrl(file) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(typeof reader.result === "string" ? reader.result : "");
        reader.onerror = () => reject(reader.error ?? new Error("file read failed"));
        reader.readAsDataURL(file);
      });
    }

    /** Downscale large local images so localStorage stays within quota. */
    function compressImage(dataUrl, maxDimension = 2560, quality = 0.86) {
      return new Promise((resolve) => {
        if (typeof Image === "undefined" || typeof document === "undefined") {
          resolve(dataUrl);
          return;
        }
        const image = new Image();
        image.onload = () => {
          const width = image.naturalWidth;
          const height = image.naturalHeight;
          if (width <= maxDimension && height <= maxDimension && dataUrl.length < 900000) {
            resolve(dataUrl);
            return;
          }
          const scale = Math.min(1, maxDimension / Math.max(width, height));
          const targetWidth = Math.max(1, Math.round(width * scale));
          const targetHeight = Math.max(1, Math.round(height * scale));
          const canvas = document.createElement("canvas");
          canvas.width = targetWidth;
          canvas.height = targetHeight;
          const context = canvas.getContext("2d");
          if (context === null) {
            resolve(dataUrl);
            return;
          }
          context.drawImage(image, 0, 0, targetWidth, targetHeight);
          try {
            const webp = canvas.toDataURL("image/webp", quality);
            if (webp.startsWith("data:image/webp")) { resolve(webp); return; }
          } catch {
            // fall through to JPEG
          }
          try {
            resolve(canvas.toDataURL("image/jpeg", quality));
          } catch {
            resolve(dataUrl);
          }
        };
        image.onerror = () => resolve(dataUrl);
        image.src = dataUrl;
      });
    }

